-- Public canonical cache and operator-local drafts are deliberately separate from records.
CREATE TABLE editorial_snapshots(community_id uuid NOT NULL,repository text NOT NULL,branch text NOT NULL,commit_sha text NOT NULL,records jsonb NOT NULL,fetched_at timestamptz NOT NULL DEFAULT now(),connection text NOT NULL DEFAULT 'online',PRIMARY KEY(community_id,repository,branch));
CREATE TABLE editorial_drafts(id uuid PRIMARY KEY,community_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),repository text NOT NULL,branch text NOT NULL,type text NOT NULL CHECK(type='events'),record_id uuid NOT NULL,base_commit text NOT NULL,base_record_hash text,base_record jsonb,payload jsonb NOT NULL,desired_status text NOT NULL CHECK(desired_status IN('published','archived')),version integer NOT NULL DEFAULT 1,state text NOT NULL DEFAULT 'local',conflict jsonb,proposal_id text,updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX editorial_drafts_owner ON editorial_drafts(community_id,actor_id,repository,branch);
CREATE TABLE editorial_proposals(id text PRIMARY KEY,community_id uuid NOT NULL,actor_id uuid NOT NULL REFERENCES users(id),repository text NOT NULL,branch text NOT NULL,base_commit text NOT NULL,request_hash text NOT NULL,actor_subject text NOT NULL,manifest jsonb NOT NULL,state text NOT NULL,remote jsonb,error_code text,recovery jsonb,lease_until timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE editorial_requests(community_id uuid NOT NULL,actor_id uuid NOT NULL,key text NOT NULL,request_hash text NOT NULL,proposal_id text NOT NULL REFERENCES editorial_proposals(id),PRIMARY KEY(community_id,actor_id,key));
CREATE TABLE editorial_submission_drafts(proposal_id text NOT NULL REFERENCES editorial_proposals(id),draft_id uuid NOT NULL,version integer NOT NULL,record_id uuid NOT NULL,PRIMARY KEY(proposal_id,draft_id,version));
INSERT INTO schema_migrations(version) VALUES(4);
